xVec2& xVec2::operator*=(float s) {
    x *= s;
    y *= s;
    return *this;
}

xVec2& xVec2::operator+=(const xVec2& o) {
    x += o.x;
    y += o.y;
    return *this;
}

xVec2& xVec2::operator-=(const xVec2& o) {
    x -= o.x;
    y -= o.y;
    return *this;
}

xVec2 xVec2::operator+(const xVec2& o) const {
    xVec2 r = *this;
    r += o;
    return r;
}

xVec2 xVec2::operator*(const xVec2& o) const {
    xVec2 r = *this;
    r.x *= o.x;
    r.y *= o.y;
    return r;
}

float std::sin(float x) {
    return ::sin(x);
}

float xinvsqrt(float x) {
    return 1.0f / Math::sqrt(x);
}

